package dev.minegame.mines;

import org.bukkit.command.*; import org.bukkit.entity.Player;

public final class ChickenAdminCommand implements CommandExecutor {
    private final ChickenManager manager; public ChickenAdminCommand(ChickenManager manager){this.manager=manager;}
    @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p)){if(args.length==1&&args[0].equalsIgnoreCase("reload")){manager.reload(sender);return true;}if(args.length==2&&args[0].equalsIgnoreCase("set")){sender.sendMessage(manager.color("&eCurrent chicken."+args[1]+" = &f"+manager.current(args[1])));sender.sendMessage(manager.color("&6Usage: &f/chickenadmin set <path> <value>"));return true;}sender.sendMessage("Only players can create, remove, regenerate, or change Chicken board settings.");return true;}if(!p.hasPermission("chicken.admin")){p.sendMessage(manager.color("&cNo permission."));return true;}if(args.length==0){p.sendMessage(manager.color("&6/chickenadmin <create [size]|remove <#>|regen [#]|list|set <path> <value>|reload>"));return true;}switch(args[0].toLowerCase()){case "create"->{int size=7;if(args.length>1)try{size=Integer.parseInt(args[1]);}catch(NumberFormatException ex){p.sendMessage(manager.color("&cSize must be a number."));return true;}manager.create(p,size);}case "remove"->{if(args.length<2){manager.list(p);return true;}try{manager.remove(p,Integer.parseInt(args[1]));}catch(NumberFormatException ex){p.sendMessage(manager.color("&cUse /chickenadmin remove <number>."));}}case "regen"->manager.regen(p,args.length>1?args[1]:null);case "list"->manager.list(p);case "set"->{if(args.length==2){p.sendMessage(manager.color("&eCurrent chicken."+args[1]+" = &f"+manager.current(args[1])));p.sendMessage(manager.color("&6Usage: &f/chickenadmin set <path> <value>"));return true;}if(args.length<3){p.sendMessage(manager.color("&6Usage: &f/chickenadmin set <path> <value>"));return true;}manager.set(p,args[1],args[2]);}case "reload"->manager.reload(p);default->p.sendMessage(manager.color("&cUnknown Chicken admin command."));}return true;}
}